mapper.insert:
INSERT INTO application_form_snapshot (
    form_version_id, source_code, source_program_id, source_fingerprint, attachment_sha256, manifest_json,
    parser_version, extraction_model, extraction_prompt_version, created_at
) VALUES (
    #{formVersionId}, #{sourceCode}, #{sourceProgramId}, #{sourceFingerprint}, #{attachmentSha256}, CAST(#{manifestJson} AS JSON),
    #{parserVersion}, #{extractionModel}, #{extractionPromptVersion}, #{createdAt}
) AS incoming
ON DUPLICATE KEY UPDATE form_version_id = incoming.form_version_id

mapper.select:
SELECT 
FROM application_form_snapshot
WHERE source_code = #{sourceCode}
  AND source_program_id = #{sourceProgramId}
  AND source_fingerprint = #{sourceFingerprint}
  AND parser_version = #{parserVersion}
  AND extraction_model = #{extractionModel}
  AND extraction_prompt_version = #{extractionPromptVersion}

mapper.update:
UPDATE application_form_snapshot
SET manifest_json = JSON_SET(manifest_json, '$.documentMapSnapshot', CAST(#{documentMapJson} AS JSON))
WHERE form_version_id = #{formVersionId} AND attachment_sha256 = #{sourceSha256}
  AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(manifest_json, '$.documentMapSnapshot.pipelineVersion')), '') != #{pipelineVersion}
